#include <bits/stdc++.h>

using namespace std;

#define RANG(i, a, b) for (int i = (a); i < (b); ++i)
#define log_error(...) fprintf(stderr, __VA_ARGS__)
#define pair_make mp
#define first_x first
#define second_y second
#define add_back pb
#define length(x) (int((x).size()))
#define range(x) (x).begin(), (x).end()

#define count_trailing __builtin_ctz
#define count_bits __builtin_popcount

template<typename T> inline bool minimize(T &a, const T &b) { if (a > b) { a = b; return true; } return false; }
template<typename T> inline bool maximize(T &a, const T &b) { if (a < b) { a = b; return true; } return false; }

typedef long long LL;

const int INF = 0x3f3f3f3f;

const int MAXN = 70;
const int MAXN2 = 50;
const int LIMIT = 22;

LL comb[MAXN + 5][MAXN + 5];

void init_comb()
{
	RANG(i, 0, MAXN)
	{
		comb[i][0] = 1;
		RANG(j, 1, i + 1)
		{
			comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
		}
	}
}

int n, m, total;
int mid_idx;
int g[MAXN + 5];

vector<pair<LL, int>> partb[MAXN2 + 5][MAXN2 + 5];

void dfs_b(int x, int cntA, int cntB, LL sum = 0)
{
	if (x == mid_idx)
	{
		partb[cntA][cntB].push_back({sum, 1});
		return;
	}
	RANG(i, 0, 2)
	{
		if (~g[x - 1] && i != g[x - 1]) continue;
		LL tmp = 0;
		if (i == 0)
		{
			if (cntA > 0)
			{
				RANG(j, 0, n) tmp += comb[cntA - 1][n - 1] * comb[cntB][j] * comb[total - x][n - j];
				dfs_b(x - 1, cntA - 1, cntB, sum + tmp);
			}
		}
		else
		{
			if (cntB > 0)
			{
				RANG(j, 0, n) tmp -= comb[cntB - 1][n - 1] * comb[cntA][j] * comb[total - x][n - j];
				dfs_b(x - 1, cntA, cntB - 1, sum + tmp);
			}
		}
	}
}

map<LL, LL> parta[MAXN2 + 5][MAXN2 + 5];

LL best_ans = LLONG_MAX, best_cnt = 0;

inline void try_update(const LL &val, const LL &cnt)
{
	if (minimize(best_ans, val)) best_cnt = cnt;
	else if (val == best_ans) best_cnt += cnt;
}

void process_parta()
{
	RANG(i, 0, n + m + 1) RANG(j, 0, n + m + 1) parta[i][j].clear();
	parta[0][0][0] = 1;
	RANG(i, 0, n + m + 1) RANG(j, 0, n + m + 1)
	{
		for (auto u : parta[i][j])
		{
			if (i + j == mid_idx)
			{
				int p = lower_bound(all(partb[i][j]), make_pair(-u.X, -1)) - partb[i][j].begin();
				if (p < length(partb[i][j])) try_update(abs(u.X + partb[i][j][p].X), u.Y * partb[i][j][p].Y);
				if (p > 0) try_update(abs(u.X + partb[i][j][p - 1].X), u.Y * partb[i][j][p - 1].Y);
			}
			else
			{
				int p = i + j;
				RANG(k, 0, 2)
				{
					if (~g[p] && k != g[p]) continue;
					int cntA = i, cntB = j;
					if (k == 0) ++cntA;
					else ++cntB;
					if (cntA <= n + m && cntB <= n + m)
					{
						LL tmp = 0;
						if (k == 0)
						{
							RANG(l, 0, n) tmp += comb[cntA - 1][n - 1] * comb[cntB][l] * comb[total - p - 1][n - l];
						}
						else
						{
							RANG(l, 0, n) tmp -= comb[cntB - 1][n - 1] * comb[cntA][l] * comb[total - p - 1][n - l];
						}
						parta[cntA][cntB][u.X + tmp] += u.Y;
					}
				}
			}
		}
	}
}

int main()
{
	init_comb();
	char s[MAXN + 5];
	scanf("%d%d%s", &n, &m, s);
	total = (n + m) << 1;
	mid_idx = max(0, total - LIMIT);
	memset(g, -1, sizeof g);
	process_parta();
	best_cnt = 0;
	RANG(i, 0, total) if (s[i] == 'A') g[i] = 0; else if (s[i] == 'B') g[i] = 1;
	process_parta();
	cout << best_cnt << endl;
	return 0;
}
